; clock.asm -- chapter 17: a frame of the program's own
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "clock.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
frames  EQU VARS + 16           ; frames counted by isr
seconds EQU VARS + 18           ; and seconds
count   EQU VARS + 20           ; frames left in this second
rate    EQU VARS + 21           ; frames in a second: 50 or 60
; A routine of the program's own counts frames and seconds; the main loop
; waits for each frame and prints them.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 10
        ld c, 8
        ld hl, t_fr
        call puts
        ld b, 12
        ld c, 8
        ld hl, t_sec
        call puts
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rlca                    ; bit 7 into the carry
        ld a, 60
        jr nc, hz60
        ld a, 50
hz60:   ld (rate), a
        ld (count), a
        ld hl, 0
        ld (frames), hl
        ld (seconds), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
main:   halt                    ; wait for the frame
        ld hl, (frames)         ; and print, a frame from the next interrupt
        ld b, 10
        ld c, 18
        call putd16
        ld hl, (seconds)
        ld b, 12
        ld c, 18
        call putd16
        jr main

; isr: every frame. Counts the frames, and the seconds: 50 frames to the
;      second on a 50 Hz machine, 60 on a 60 Hz one. Keeps AF and HL.
isr:    push af
        push hl
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        ld hl, (frames)
        inc hl
        ld (frames), hl
        ld hl, count
        dec (hl)                ; frames left in this second
        jr nz, isr1
        ld a, (rate)
        ld (hl), a              ; a new second
        ld hl, (seconds)
        inc hl
        ld (seconds), hl
isr1:   pop hl
        pop af
        ei
        ret

t_fr:   db "frames", 0
t_sec:  db "seconds", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putd16: HL = a number (0-65535) as five characters, right-aligned.
;         B = row, C = column; C moves on by 5. Uses A, DE, HL.
putd16: push bc
        ld de, d16buf
        ld bc, -10000
        call .digit
        ld bc, -1000
        call .digit
        ld bc, -100
        call .digit
        ld bc, -10
        call .digit
        ld a, l
        add a, '0'
        ld (de), a              ; the units, always printed
        ld hl, d16buf
        ld b, 4
.blank: ld a, (hl)              ; leading zeros become spaces
        cp '0'
        jr nz, .print
        ld (hl), ' '
        inc hl
        djnz .blank
.print: pop bc
        ld hl, d16buf
        ld e, 5
.out:   ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, .out
        ret
.digit: ld a, '0' - 1           ; how many times BC fits: subtract until it goes below
.sub:   inc a
        add hl, bc              ; BC is negative: the carry means it still fitted
        jr c, .sub
        sbc hl, bc              ; one too many: add it back (the carry is clear)
        ld (de), a
        inc de
        ret
d16buf  EQU VARS + 4            ; 5 bytes of RAM, after numbuf
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
